CREATE TABLE "baking_conversion_references" (
	"id" text PRIMARY KEY,
	"business_id" uuid,
	"reference_id" text,
	"inventory_ingredient_id" text,
	"ingredient_name" text NOT NULL,
	"description" text NOT NULL,
	"reference_weight_g" numeric NOT NULL,
	"reference_volume_ml" numeric NOT NULL,
	"original_quantity" numeric NOT NULL,
	"original_unit" text NOT NULL,
	"source_name" text NOT NULL,
	"source_url" text NOT NULL,
	"brand" text,
	"scope" text NOT NULL,
	CONSTRAINT "baking_positive_basis" CHECK ("reference_weight_g" > 0 AND "reference_volume_ml" > 0 AND "original_quantity" > 0),
	CONSTRAINT "baking_reference_scope" CHECK (("scope" = 'shared' AND "business_id" IS NULL AND "inventory_ingredient_id" IS NULL) OR ("scope" = 'private' AND "business_id" IS NOT NULL))
);
