ALTER TABLE baking_conversion_references ENABLE ROW LEVEL SECURITY;
ALTER TABLE baking_conversion_references FORCE ROW LEVEL SECURITY;
CREATE POLICY baking_reference_read ON baking_conversion_references FOR SELECT USING (scope='shared' OR business_id=NULLIF(current_setting('app.business_id',true),'')::uuid);
CREATE POLICY baking_reference_insert ON baking_conversion_references FOR INSERT WITH CHECK (scope='private' AND business_id=NULLIF(current_setting('app.business_id',true),'')::uuid);
CREATE POLICY baking_reference_update ON baking_conversion_references FOR UPDATE USING (scope='private' AND business_id=NULLIF(current_setting('app.business_id',true),'')::uuid) WITH CHECK (scope='private' AND business_id=NULLIF(current_setting('app.business_id',true),'')::uuid);
